def find_closet(arr1, arr2, arr3, k1, k2, k3):
    def binary_search(arr, target):
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_closest(arr, target):
        index = binary_search(arr, target)
        if index == 0:
            return arr[0]
        elif index == len(arr):
            return arr[-1]
        else:
            left_diff = abs(arr[index - 1] - target)
            right_diff = abs(arr[index] - target)
            if left_diff <= right_diff:
                return arr[index - 1]
            else:
                return arr[index]

    closest_elements = []
    for i in range(k1):
        closest_elements.append(find_closest(arr1, arr2[i]))
    for i in range(k2):
        closest_elements.append(find_closest(arr2, arr3[i]))
    for i in range(k3):
        closest_elements.append(find_closest(arr3, arr1[i]))

    closest_elements.sort()
    return tuple(closest_elements[:3])

